//! Strong normal plan inventory -> original Signal/MLDSA unseal and once sign.
//! No QA ApprovedSourceFrame is constructed, accepted or imported.
use crate::{server::Guard,raw::Status,plan::NormalQualifiedFrame,loaded_pair::NormalLoadedPair};
use std::{cell::RefCell,collections::HashMap,ffi::c_void,rc::Rc,ptr};
#[repr(C)]struct HoldToken{serial:u64}
struct Holds{next:u64,tokens:Vec<Box<HoldToken>>,owners:HashMap<usize,Rc<Guard>>}
thread_local!{static HOLDS:RefCell<Holds>=RefCell::new(Holds{next:0,tokens:Vec::new(),owners:HashMap::new()});}
fn hold(g:Rc<Guard>)->Result<*mut c_void,Status>{g.key_current()?;if g.children.get()==u64::MAX{return Err(Status::error(8))}HOLDS.with(|i|{let mut i=i.borrow_mut();if i.next>=16384{return Err(Status::error(8))}i.next+=1;let mut token=Box::new(HoldToken{serial:i.next});let raw=(&mut *token)as*mut HoldToken as*mut c_void;i.tokens.push(token);g.children.set(g.children.get()+1);i.owners.insert(raw as usize,g);Ok(raw)})}
fn lookup(p:*mut c_void)->Option<Rc<Guard>>{HOLDS.with(|i|i.borrow().owners.get(&(p as usize)).cloned())}
#[unsafe(no_mangle)]unsafe extern "C" fn ynx_social_finite_joint_plan_hold_open_v1(context:*mut c_void,out:*mut *mut c_void,status:*mut Status){if status.is_null(){return}if out.is_null(){unsafe{*status=Status::error(2)};return}unsafe{*out=ptr::null_mut()};let result=crate::transport::lookup_guard(context).ok_or(Status::error(1)).and_then(hold);match result{Ok(p)=>unsafe{*out=p;*status=Status::ok()},Err(e)=>unsafe{*status=e}}}
#[unsafe(no_mangle)]unsafe extern "C" fn ynx_social_finite_joint_plan_current_v1(p:*mut c_void,status:*mut Status){if status.is_null(){return}let result=lookup(p).ok_or(Status::error(1)).and_then(|g|g.key_current());unsafe{*status=result.err().unwrap_or(Status::ok())}}
#[repr(C)]struct Span{data:*const u8,size:usize}
#[repr(C)]struct View{version:u32,size:u32,role:u32,uid:u32,gid:u32,reserved:u32,dir:i32,reserved_fd:i32,generation:u64,classic:[u8;33],pq:[u8;2592],bundle:[u8;32],alias:Span,custodian:Span,body:Span,frame:Span,journal:*mut c_void}
#[unsafe(no_mangle)]unsafe extern "C" fn ynx_social_finite_joint_plan_view_v1_copy(p:*mut c_void,out:*mut View,status:*mut Status){if status.is_null(){return}if out.is_null(){unsafe{*status=Status::error(2)};return}unsafe{*out=std::mem::zeroed()};let result=(||{let g=lookup(p).ok_or(Status::error(1))?;g.key_current()?;let f=g.facts.borrow();let f=f.as_ref().ok_or(Status::error(8))?;let span=|s:&[u8]|Span{data:s.as_ptr(),size:s.len()};let v=View{version:1,size:std::mem::size_of::<View>()as u32,role:g.row.role,uid:g.row.provider_uid,gid:g.row.provider_gid,reserved:0,dir:g.own_fd()?,reserved_fd:0,generation:g.row.storage_generation,classic:f.classic,pq:f.pq,bundle:g.row.bundle_sha256,alias:span(g.row.alias.as_bytes()),custodian:span(g.row.custodian.as_bytes()),body:span(&g.request.body),frame:span(&g.request.frame),journal:g.journal.get()};unsafe{*out=v};drop(f);g.key_current()})();unsafe{*status=result.err().unwrap_or(Status::ok())}}
#[unsafe(no_mangle)]unsafe extern "C" fn ynx_social_finite_joint_plan_hold_close_v1(p:*mut *mut c_void,status:*mut Status){if status.is_null(){return}if p.is_null(){unsafe{*status=Status::error(2)};return}let raw=unsafe{*p};let g=lookup(raw);if let Some(g)=g{if g.children.get()==0{unsafe{*status=Status::error(8)};return}HOLDS.with(|i|{i.borrow_mut().owners.remove(&(raw as usize));});g.children.set(g.children.get()-1);unsafe{*p=ptr::null_mut();*status=Status{done:1,..g.first.get().unwrap_or(Status::ok())}}}else{unsafe{*status=Status::error(1)}}}
pub(crate)struct KeyOwner{plan:Option<Box<NormalQualifiedFrame>>,partial_hold:*mut c_void,pair:Option<NormalLoadedPair>,first:Option<Status>,closed:bool}
impl KeyOwner{
 pub(crate)fn open_guard(g:Rc<Guard>)->(Box<Self>,Result<(),Status>){let mut owner=Box::new(Self{plan:None,partial_hold:ptr::null_mut(),pair:None,first:None,closed:false});let result=(||{g.key_current()?;let held=hold(g)?;owner.partial_hold=held;let plan=unsafe{NormalQualifiedFrame::from_existing_hold(held)}.map_err(|(c,_)|Status::error(c))?;owner.partial_hold=ptr::null_mut();owner.plan=Some(plan);let plan=owner.plan.as_ref().unwrap();match NormalLoadedPair::load(plan){Ok(pair)=>owner.pair=Some(pair),Err((code,pair))=>{owner.pair=Some(pair);return Err(Status::error(code))}}Ok(())})();if let Err(e)=result{owner.first=Some(e)}(owner,result)}
 pub(crate)fn sign(&mut self)->Result<(),Status>{if let Some(s)=self.first{return Err(s)}let plan=self.plan.as_ref().ok_or(Status::error(8))?;let mut journal=crate::journal::Journal{original:plan.journal};let result=self.pair.as_mut().ok_or(Status::error(8))?.sign_once(plan,&mut journal).map_err(Status::error);if let Err(s)=result{self.first=Some(s)}result}
 pub(crate)fn close(&mut self)->Status{if self.closed{return Status{done:1,..self.first.unwrap_or(Status::ok())}}if let Some(pair)=self.pair.as_mut(){if let Err(c)=pair.close(){if self.first.is_none(){self.first=Some(Status::error(c))}}if pair.has_debt(){return Status{done:0,unknown:1,..self.first.unwrap_or(Status::error(8))}}self.pair=None;}if let Some(plan)=self.plan.as_mut(){let(done,c)=plan.close();if c!=0&&self.first.is_none(){self.first=Some(Status::error(c))}if !done{return Status{done:0,unknown:1,..self.first.unwrap_or(Status::error(8))}}self.plan=None;}if !self.partial_hold.is_null(){let mut s=Status::default();unsafe{ynx_social_finite_joint_plan_hold_close_v1(&mut self.partial_hold,&mut s)};if s.result().is_err()&&self.first.is_none(){self.first=Some(s)}if !self.partial_hold.is_null()||s.done!=1{return Status{done:0,unknown:1,..self.first.unwrap_or(Status::error(8))}}}self.closed=true;Status{done:1,..self.first.unwrap_or(Status::ok())}}
}
impl Drop for KeyOwner{fn drop(&mut self){if !self.closed{std::process::abort()}}}
